import React, { useRef, useState, useCallback, useEffect } from "react";

/**
 * GrandGates — "natural & optimistic" variant
 * -----------------------------------------------------------------------
 * Same drag-to-open mechanic as before, restyled: warm cream/blush
 * background, gold + sage botanical vine artwork instead of dark
 * gold-on-black paneling, soft dawn-toned light spill.
 *
 * The door artwork is ONE illustrated door leaf (arched top, hinges
 * on its left edge, vines flowing toward its right edge), used twice:
 * the LEFT door uses it as-is — hinges already land on the outer/left
 * frame edge, vines already flow toward the center seam. The RIGHT
 * door is the same image mirrored (`scaleX(-1)`), so its hinges land
 * on the outer/right edge and its vines flow toward the seam too.
 * Net effect: two matching leaves, hinges out, florals meeting in
 * the middle like a real double door.
 *
 * PRODUCTION NOTE: this file embeds the artwork as a base64 data URI
 * ONLY so it previews standalone here. In your real project, delete
 * DOOR_VINE_IMG and instead add a normal ES module import of your
 * full-res door-vine PNG from your assets folder, then use that
 * imported value in the two <img> src props below. That keeps your
 * bundle sane (this preview uses a downscaled/compressed copy).
 *
 * Element IDs (door-left / door-right / lock-body / monogram-text /
 * light-spill) still match your asset contract for the GSAP port.
 */

