const NAME_LEFT = "Ahmed";
const NAME_RIGHT = "Layla";

export default function GrandGates({ names = "A & L", onOpened, onTransitionComplete, onInteractionStart }) {
  const containerRef = useRef(null);
  const draggingRef = useRef(false);
  const startXRef = useRef(0);
  const [progress, setProgress] = useState(0); // 0 = closed, 1 = fully open
  const [isAnimating, setIsAnimating] = useState(false);
  const [opened, setOpened] = useState(false);
  const [fontsReady, setFontsReady] = useState(false);

  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Cinzel:wght@500;600&display=swap";
    document.head.appendChild(link);
    link.onload = () => setFontsReady(true);
    const fallback = setTimeout(() => setFontsReady(true), 400);
    return () => {
      clearTimeout(fallback);
      document.head.removeChild(link);
    };
  }, []);

  // Increased threshold so the door opens much slower relative to finger movement (feels heavier)
  const OPEN_THRESHOLD_PX = 800;
  // Adjusted snap ratio so they still only need to pull it a reasonable physical distance to trigger
  const RELEASE_SNAP_RATIO = 0.25;

  const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

  const settleOpen = useCallback(() => {
    setIsAnimating(true);
    setProgress(1);
    window.setTimeout(() => {
      setIsAnimating(false);
      setOpened(true);
      onOpened && onOpened();
      
      // Cinematic transition: wait for bloom to expand, then dissolve the whole component
      window.setTimeout(() => {
        onTransitionComplete && onTransitionComplete();
      }, 650); // 0.65s fade out duration
    }, 2000);
  }, [onOpened, onTransitionComplete]);

  const settleClosed = useCallback(() => {
    setIsAnimating(true);
    setProgress(0);
    window.setTimeout(() => setIsAnimating(false), 450);
  }, []);

  const handlePointerDown = (e) => {
    if (opened) return;
    if (!draggingRef.current && onInteractionStart) onInteractionStart();
    draggingRef.current = true;
    startXRef.current = e.clientX ?? e.touches?.[0]?.clientX ?? 0;
    setIsAnimating(false);
    containerRef.current?.setPointerCapture?.(e.pointerId);
  };

  const handlePointerMove = (e) => {
    if (!draggingRef.current || opened) return;
    const x = e.clientX ?? e.touches?.[0]?.clientX ?? 0;
    const delta = Math.abs(x - startXRef.current);
    const p = clamp(delta / OPEN_THRESHOLD_PX, 0, 1);
    setProgress(p);
  };

  const handlePointerUp = () => {
    if (!draggingRef.current || opened) return;
    draggingRef.current = false;
    if (progress >= RELEASE_SNAP_RATIO) {
      settleOpen();
    } else {
      settleClosed();
    }
  };

  const handleReset = () => {
    setOpened(false);
    setProgress(0);
  };

  const doorTransition = isAnimating
    ? "transform 2000ms cubic-bezier(0.16, 1, 0.3, 1)"
    : draggingRef.current
    ? "none"
    : "transform 300ms ease-out";

  // Hinge-swing, not slide-apart: each door rotates around its OUTER
  // edge (where the illustrated hinges sit) using rotateY inside a
  // perspective container. The far/seam edge sweeps backward and
  // foreshortens as it opens — that's what reads as a heavy hinged
  // gate instead of a sliding mall door. MAX_SWING_DEG a bit past 90
  // so the door settles as if resting open against the frame.
  const MAX_SWING_DEG = 108;

  const [autoDemoProgress, setAutoDemoProgress] = useState(0);

  // Auto-demo: periodically nudge doors open to show the gesture
  useEffect(() => {
    if (opened) return;
    let frame;
    const DEMO_DURATION = 900;
    const PAUSE_DURATION = 2800;
    let phase = 'pausing';
    let phaseStart = Date.now();

    const tick = () => {
      if (opened) return;
      const now = Date.now();
      const elapsed = now - phaseStart;

      if (phase === 'pausing') {
        if (elapsed > PAUSE_DURATION) { phase = 'opening'; phaseStart = now; }
        setAutoDemoProgress(0);
      } else if (phase === 'opening') {
        const t = Math.min(elapsed / DEMO_DURATION, 1);
        const eased = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
        const p = eased * 0.22;
        if (!draggingRef.current) setAutoDemoProgress(p);
        if (t >= 1) { phase = 'closing'; phaseStart = now; }
      } else if (phase === 'closing') {
        const t = Math.min(elapsed / DEMO_DURATION, 1);
        const eased = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
        const p = (1 - eased) * 0.22;
        if (!draggingRef.current) setAutoDemoProgress(p);
        if (t >= 1) { phase = 'pausing'; phaseStart = now; setAutoDemoProgress(0); }
      }

      frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [opened]);

  const effectiveProgress = draggingRef.current || progress > 0 ? progress : autoDemoProgress;

  const leftDoorStyle = {
    transform: `rotateY(${-effectiveProgress * MAX_SWING_DEG}deg)`,
    transition: isAnimating
      ? "transform 2000ms cubic-bezier(0.16, 1, 0.3, 1)"
      : draggingRef.current
      ? "none"
      : "transform 300ms ease-out",
    transformOrigin: "left center",
  };
  const rightDoorStyle = {
    transform: `rotateY(${effectiveProgress * MAX_SWING_DEG}deg)`,
    transition: isAnimating
      ? "transform 2000ms cubic-bezier(0.16, 1, 0.3, 1)"
      : draggingRef.current
      ? "none"
      : "transform 300ms ease-out",
    transformOrigin: "right center",
  };

  const glowOpacity = clamp(effectiveProgress * 1.4, 0, 1);
  const lockOpacity = 1 - clamp(effectiveProgress / 0.35, 0, 1);
  const lockScale = 1 + effectiveProgress * 0.15;

  const [fadeComplete, setFadeComplete] = useState(false);

  useEffect(() => {
    if (opened) {
      // Start fading out the entire gates component 50ms after it opens fully
      const timer = setTimeout(() => setFadeComplete(true), 50);
      return () => clearTimeout(timer);
    }
  }, [opened]);

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        height: "100dvh",
        overflow: "hidden",
        zIndex: 1,
        background:
          "radial-gradient(120% 90% at 50% 25%, #FBF6EC 0%, #F4EDE0 55%, #EFE6D3 100%)",
        fontFamily: fontsReady ? "'Cormorant Garamond', serif" : "serif",
        userSelect: "none",
        touchAction: "none",
        pointerEvents: opened ? "none" : "auto",
        opacity: fadeComplete ? 0 : 1,
        transition: "opacity 600ms ease-in-out",
      }}
    >

      {/* ---- Cinematic light bloom expanding on open ---- */}
      <div
        id="light-spill"
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          left: "50%",
          width: opened ? "200vw" : 280,
          transform: "translateX(-50%)",
          background: opened 
            ? "radial-gradient(closest-side, rgba(255,246,230,1), rgba(255,241,214,0.8) 45%, transparent 75%)"
            : "radial-gradient(closest-side, rgba(255,241,214,0.95), rgba(247,224,175,0.35) 45%, transparent 75%)",
          filter: opened ? "blur(20px)" : "blur(8px)",
          opacity: opened ? 1 : Math.max(glowOpacity, fadeComplete ? 0 : 0),
          pointerEvents: "none",
          transition: opened ? "width 0.6s ease-out, filter 0.6s ease-out, opacity 0.6s ease-out, background 0.6s ease" : "none",
          zIndex: opened ? 10 : 0,
        }}
      />

      {/* ---- Doors ---- */}
      <div
        ref={containerRef}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          cursor: opened ? "default" : "grab",
          perspective: 1700,
          perspectiveOrigin: "50% 50%",
        }}
      >
        <Door id="door-left" side="left" style={leftDoorStyle} name={NAME_LEFT} />
        <Door id="door-right" side="right" style={rightDoorStyle} name={NAME_RIGHT} />
      </div>

      {/*
        ---- Pull handle ----
        Replaces a purely decorative monogram with an actually
        graspable affordance, following the "slide to unlock" precedent:
        stack three redundant signifiers so the gesture is obvious to
        anyone regardless of age or reading ability —
          1. SHAPE  a ring that visually reads as a physical handle
          2. MOTION a self-playing "tug" demo before anyone touches it,
             so the exact gesture is shown, not just implied
          3. TEXT   a short, plain, close-by label ("PULL")
        A generous invisible hit area (well past standard 44px touch
        target minimums) means an imprecise grab still works — this
        matters most for users with less motor precision.
      */}
      <div
        id="lock-body"
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: `translate(-50%, -50%) scale(${lockScale})`,
          opacity: lockOpacity,
          pointerEvents: "none",
          transition: isAnimating ? "opacity 500ms ease" : "none",
        }}
      >
        <PullHandle isDragging={draggingRef.current} progress={progress} />
      </div>

      {/* ---- Nameplate (decorative only — kept separate from the
           interactive handle so nothing actionable is disguised as
           decoration, and vice versa) ---- */}
      {!opened && (
        <div
          style={{
            position: "absolute",
            top: 28,
            left: 0,
            right: 0,
            textAlign: "center",
            color: "#A88749",
            opacity: clamp(1 - progress * 2, 0, 1),
            pointerEvents: "none",
            fontFamily: "'Cormorant Garamond', serif",
            fontStyle: "italic",
            fontSize: 22,
            letterSpacing: "0.04em",
          }}
        >
          {names}
        </div>
      )}

      {/* ---- Instruction ---- */}
      {!opened && (
        <div
          style={{
            position: "absolute",
            bottom: 36,
            left: 0,
            right: 0,
            textAlign: "center",
            color: "#A88749",
            opacity: 1 - progress,
            transition: "opacity 200ms ease",
            pointerEvents: "none",
          }}
        >
          <div
            style={{
              fontFamily: "'Cinzel', serif",
              fontSize: 13,
              letterSpacing: "0.25em",
              opacity: 0.9,
              marginBottom: 8,
              fontWeight: 600,
            }}
          >
            PULL THE DOORS APART
          </div>
          <div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
            fontSize: 22,
          }}>
            <span style={{ animation: "gg-swipe-l 1.4s ease-in-out infinite", display: "inline-block" }}>👈</span>
            <span style={{ fontSize: 11, letterSpacing: "0.2em", color: "#A88749", opacity: 0.7 }}>SWIPE</span>
            <span style={{ animation: "gg-swipe-r 1.4s ease-in-out infinite", display: "inline-block" }}>👉</span>
          </div>
        </div>
      )}

      {opened && (
        <button
          onClick={handleReset}
          style={{
            position: "absolute",
            top: 16,
            right: 16,
            background: "rgba(0,0,0,0.05)",
            color: "#8A6D2F",
            border: "1px solid rgba(154,122,60,0.35)",
            borderRadius: 999,
            padding: "6px 14px",
            fontSize: 12,
            letterSpacing: "0.08em",
            cursor: "pointer",
            fontFamily: "'Cinzel', serif",
          }}
        >
          RESET
        </button>
      )}
    </div>
  );
}

function Door({ id, side, style, name }) {
  const isLeft = side === "left";
  return (
    <div
      id={id}
      data-role={isLeft ? "door-left" : "door-right"}
      style={{
        width: "50%",
        height: "100%",
        position: "relative",
        overflow: "hidden",
        background: "#F6F0E3",
        backfaceVisibility: "hidden",
        WebkitBackfaceVisibility: "hidden",
        boxShadow: isLeft
          ? "inset -18px 0 40px rgba(154,122,60,0.08)"
          : "inset 18px 0 40px rgba(154,122,60,0.08)",
        ...style,
      }}
    >
      {/*
        Full illustrated door leaf: hinges on its native left edge,
        vines flowing toward its native right edge. Left door = as-is
        (hinges land on the outer frame edge). Right door = mirrored
        (scaleX(-1)) so its hinges land on the outer edge too, and
        both leaves' vines meet at the center seam.
      */}
      <img
        src={DOOR_VINE_IMG}
        alt=""
        draggable={false}
        onDragStart={(e) => e.preventDefault()}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          objectFit: "cover",
          objectPosition: "center",
          transform: isLeft ? "scaleX(1)" : "scaleX(-1)",
          pointerEvents: "none",
          WebkitUserDrag: "none",
          userSelect: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          top: "20%",
          [isLeft ? "left" : "right"]: "10%",
          color: "#A88749",
          fontFamily: "'Cinzel', serif",
          fontSize: 11,
          letterSpacing: "0.25em",
          opacity: 0.55,
          writingMode: "vertical-rl",
          textOrientation: "mixed",
        }}
      >
        {name.toUpperCase()}
      </div>
    </div>
  );
}

function PullHandle({ isDragging, progress }) {
  // Once the person has actually started interacting, stop the demo
  // loop — a looping animation competing with a live drag reads as
  // broken/laggy rather than helpful.
  const demoActive = !isDragging && progress < 0.03;

  return (
    <div
      style={{
        position: "relative",
        width: 96,
        height: 96,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <style>{`
        @keyframes gg-tug {
          0%, 15%  { transform: translateX(0) scale(1); }
          7%       { transform: translateX(-14px) scale(1.06); }
          30%, 100%{ transform: translateX(0) scale(1); }
        }
        @keyframes gg-arrow-l {
          0%, 100% { opacity: 0.3; transform: translateX(0); }
          50% { opacity: 1; transform: translateX(-12px); }
        }
        @keyframes gg-arrow-r {
          0%, 100% { opacity: 0.3; transform: translateX(0); }
          50% { opacity: 1; transform: translateX(12px); }
        }
        @keyframes gg-swipe-l {
          0%, 100% { transform: translateX(0); opacity: 0.7; }
          50% { transform: translateX(-10px); opacity: 1; }
        }
        @keyframes gg-swipe-r {
          0%, 100% { transform: translateX(0); opacity: 0.7; }
          50% { transform: translateX(10px); opacity: 1; }
        }
        @keyframes gg-pulse-ring {
          0%   { transform: scale(1);   opacity: 0.6; }
          70%  { transform: scale(1.7); opacity: 0; }
          100% { transform: scale(1.7); opacity: 0; }
        }
      `}</style>

      {/* pulsing ring behind handle */}
      {demoActive && (
        <div style={{
          position: "absolute",
          width: 70,
          height: 70,
          borderRadius: "50%",
          border: "2.5px solid rgba(184,147,76,0.6)",
          animation: "gg-pulse-ring 1.6s ease-out infinite",
        }} />
      )}

      {/* outward direction arrows */}
      <svg
        width="26"
        height="20"
        viewBox="0 0 26 20"
        style={{
          position: "absolute",
          left: -44,
          animation: demoActive ? "gg-arrow-l 1.4s ease-in-out infinite" : "none",
          opacity: demoActive ? undefined : 0,
          transition: "opacity 300ms ease",
        }}
      >
        <path d="M22 2L4 10L22 18" stroke="#A88749" strokeWidth="2.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      <svg
        width="26"
        height="20"
        viewBox="0 0 26 20"
        style={{
          position: "absolute",
          right: -44,
          animation: demoActive ? "gg-arrow-r 1.4s ease-in-out infinite" : "none",
          opacity: demoActive ? undefined : 0,
          transition: "opacity 300ms ease",
        }}
      >
        <path d="M4 2L22 10L4 18" stroke="#A88749" strokeWidth="2.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
      </svg>

      {/* the ring handle */}
      <div
        style={{
          width: 68,
          height: 68,
          borderRadius: "50%",
          border: "5px solid #B8934C",
          background:
            "radial-gradient(closest-side at 35% 30%, #FFF9EC 0%, #F1E1B8 60%, #DCC384 100%)",
          boxShadow:
            "0 4px 16px rgba(120,90,30,0.45), inset 0 1px 3px rgba(255,255,255,0.6), inset 0 -3px 6px rgba(120,90,30,0.25)",
          animation: demoActive ? "gg-tug 2.2s ease-in-out infinite" : "none",
          flexShrink: 0,
        }}
      />

      <div
        style={{
          position: "absolute",
          bottom: -32,
          left: 0,
          right: 0,
          textAlign: "center",
          fontFamily: "'Cinzel', serif",
          fontSize: 12,
          letterSpacing: "0.22em",
          color: "#8A6D2F",
          fontWeight: 600,
          opacity: demoActive ? 1 : 0,
          transition: "opacity 300ms ease",
        }}
      >
        PULL OPEN
      </div>
    </div>
  );
}
